import{_ as i,o as a,c as o,a4 as t}from"./chunks/framework.B-3VpRq4.js";const c=JSON.parse('{"title":"面试题库","description":"","frontmatter":{},"headers":[],"relativePath":"interview/index.md","filePath":"interview/index.md"}'),e={name:"interview/index.md"};function r(n,l,s,u,h,q){return a(),o("div",null,[...l[0]||(l[0]=[t('<h1 id="面试题库" tabindex="-1">面试题库 <a class="header-anchor" href="#面试题库" aria-label="Permalink to &quot;面试题库&quot;">​</a></h1><blockquote><p>🧠 <strong>面试会从这份题库中随机抽取 2~3 题</strong>，大家可以提前查看熟悉。 不用背答案——面试官更看重你的思考过程和热情，而不是标准答案。</p></blockquote><hr><h2 id="📖-规则题-通用-共-18-题" tabindex="-1">📖 规则题（通用，共 18 题） <a class="header-anchor" href="#📖-规则题-通用-共-18-题" aria-label="Permalink to &quot;📖 规则题（通用，共 18 题）&quot;">​</a></h2><p><em>参考《RoboMaster 2027 高校系列赛规则变更前瞻手册》</em></p><ol><li>机器人阵容包括哪六个种类？</li><li>操作手一共有几个（包括指挥手）？</li><li>RM2027 赛季的比赛场地移除了哪两个区域？</li><li>重装机器人在三级/四级时，射击热量上限是多少？</li><li>模块化 42mm 发射机构能否安装电池？</li><li>自定义终端是由哪两个设备合并而来的？</li><li>占领己方制高点增益点后，机器人可以获得什么增益？</li><li>机器人仅按顺序检测到隧道入口和出口（跨越隧道），可以获得什么增益？持续时间多久？</li><li>机器人按顺序检测到隧道入口、内部和出口（穿越隧道），可以获得什么增益？持续时间多久？</li><li>同一台机器人需要在多少秒内按序检测到隧道的交互模块卡才能获得增益？</li><li>补给区包括哪些部分？（列出至少两个）</li><li>重装机器人比赛阶段如何补充允许发弹量？</li><li>如果比赛进行到 5 分钟时重装机器人仍未完成三级装配，能否解锁？</li><li>空中机器人是否允许安装发射机构？</li><li>机库给空中机器人提供初始动力时，方向有何限制？</li><li>工作台的主要功能是什么？</li><li>RM2027 赛季新增了哪些场地元素？</li><li>发射机构的最大工作电压是多少？</li></ol><hr><h2 id="🔧-专业题-按意向组别抽取-共-15-题" tabindex="-1">🔧 专业题（按意向组别抽取，共 15 题） <a class="header-anchor" href="#🔧-专业题-按意向组别抽取-共-15-题" aria-label="Permalink to &quot;🔧 专业题（按意向组别抽取，共 15 题）&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">按第一意向组别作答</p><p>面试时主要考察<strong>你第一意向组别</strong>的专业题，其他组的题目了解即可。</p></div><h3 id="🛠️-机械组" tabindex="-1">🛠️ 机械组 <a class="header-anchor" href="#🛠️-机械组" aria-label="Permalink to &quot;🛠️ 机械组&quot;">​</a></h3><ol><li>隧道有&quot;跨越&quot;和&quot;穿越&quot;两种通过方式，机器人底盘机械设计如何兼顾两种模式的通行性？</li><li>重装机器人收纳尺寸要求存在一种状态 ≤600×600×600mm，但伸展后可达 1200×1200×1100mm，请举例一种变形机构设计方案。</li><li>制高点有三级台阶，机器人需攀越进入，请简述底盘设计如何应对台阶障碍？</li></ol><h3 id="⚡-电控组" tabindex="-1">⚡ 电控组 <a class="header-anchor" href="#⚡-电控组" aria-label="Permalink to &quot;⚡ 电控组&quot;">​</a></h3><ol><li>重装机器人模块化 42mm 发射机构的解锁条件包括&quot;完成三级装配&quot;、&quot;比赛进行 5 分钟&quot;、&quot;队伍落后提前解锁&quot;，电控如何通过裁判系统获取这些信息并控制解锁？</li><li>制高点增益需要&quot;占领&quot;，即机器人停在增益点，电控如何判断机器人是否成功占领？（结合场地交互模块）</li><li>重装机器人可装配能量单元获取团队增益，电控如何记录当前装配等级并影响属性（如血量、热量）？</li></ol><h3 id="🔌-硬件组" tabindex="-1">🔌 硬件组 <a class="header-anchor" href="#🔌-硬件组" aria-label="Permalink to &quot;🔌 硬件组&quot;">​</a></h3><ol><li>重装机器人主机体最大工作电压 30V，模块化 42mm 发射机构最大 140V，且要求电气隔离，请设计电源系统架构？</li><li>机库最大供电 300Wh，需给空中机器人提供初始动力（弹射），请设计动力输出电路的硬件方案？</li><li>重装机器人最大供电总容量 300Wh，如何设计电池管理系统（BMS）及电量监测？</li></ol><h3 id="👁️-视觉组" tabindex="-1">👁️ 视觉组 <a class="header-anchor" href="#👁️-视觉组" aria-label="Permalink to &quot;👁️ 视觉组&quot;">​</a></h3><ol><li>制高点占领后给 50% 防御并允许非远程兑换发弹量，视觉如何判断&quot;机器人确实占领制高点&quot;而不是只在台阶下经过？</li><li>操作间配相机图传接收端及支架，若多台机器人同时图传，视觉组要做多路小窗 + 自动切换高威胁画面，怎么设计优先级？</li><li>自定义终端要&quot;接收机器人图传并叠加自制 UI&quot;，例如血量、经济、发弹量、隧道/制高点增益状态，你如何把 OpenCV/Qt 界面与裁判系统 MQTT 数据同步，避免画面和数据显示不同步？</li></ol><h3 id="📣-运营组" tabindex="-1">📣 运营组 <a class="header-anchor" href="#📣-运营组" aria-label="Permalink to &quot;📣 运营组&quot;">​</a></h3><ol><li>2027 把英雄 + 工程合并&quot;重装机器人&quot;、飞坡改隧道、新增机库/制高点，如果做一条招新短视频，30 秒讲清&quot;今年为什么值得来&quot;，脚本怎么搭？</li><li>技术组同学不爱写宣传素材，你作为宣运组长，怎么把&quot;重装模块化 42mm 解锁条件&quot;&quot;空中全包围桨叶&quot;这类技术点变成公众号可读内容？</li><li>官方要求自定义终端不得无线，但宣运拍比赛常要移动直播/传图，操作间有线环境下你怎么解决多机位素材回传？</li></ol><hr><h2 id="💭-开放题-共-5-题" tabindex="-1">💭 开放题（共 5 题） <a class="header-anchor" href="#💭-开放题-共-5-题" aria-label="Permalink to &quot;💭 开放题（共 5 题）&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">现场可能会稍有细微变动</p><p>以下问题没有标准答案，说出你真实的想法就好。</p></div><ol><li>RoboMaster 的技术迭代很快，今年的规则明年可能就变了。你怎么对待&quot;技术过时&quot;这件事？你会怎么保持自己的竞争力？</li><li>比赛现场经常会出现意想不到的状况，比如裁判系统断连、机器人突然不受控。如果你在场上担任技术保障，遇到这种情况，你的第一反应是什么？</li><li>你为什么想加入 RoboMaster 协会？除了&quot;喜欢机器人&quot;之外，你具体希望从中获得什么？</li><li>比赛规则要求机器人在尺寸和重量上有严格限制，但功能上又想做到极致——既要射得准，又要跑得快，还要能防御。当机械、电控、视觉在方案评审时互不相让，都觉得自己的需求最优先，作为项目负责人或普通成员你怎么推动决策？</li><li>如果让你给 RoboMaster 赛事组委会提一个建议，你觉得目前的比赛或者高校社团运营模式有什么可以改进的地方？</li></ol><hr><h2 id="🎯-面试小贴士" tabindex="-1">🎯 面试小贴士 <a class="header-anchor" href="#🎯-面试小贴士" aria-label="Permalink to &quot;🎯 面试小贴士&quot;">​</a></h2><ul><li><strong>别紧张</strong>：我们都是学长学姐，面试更像一次技术聊天</li><li><strong>重思路</strong>：题目答不全没关系，把你的思考过程说出来比沉默更有价值</li><li><strong>敢提问</strong>：听不懂题意可以直接问，面试中主动沟通是加分项</li><li><strong>回到投票</strong>：还没选面试时间？<a href="/arkrobomaster/recruitment/">点这里去投票 →</a></li></ul>',26)])])}const m=i(e,[["render",r]]);export{c as __pageData,m as default};
